386	/* ---------- Carte Google Maps ---------- */
387	let mapsPromise = null;
388	function loadGoogleMaps(key) {
389	  if (window.google && window.google.maps) return Promise.resolve();
390	  if (mapsPromise) return mapsPromise;
391	  mapsPromise = new Promise((resolve, reject) => {
392	    window.__mapsReady = resolve;
393	    window.gm_authFailure = () => toast("Clé Google Maps refusée : vérifie-la dans la console Google Cloud.", "error");
394	    const s = document.createElement("script");
395	    s.src = `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&callback=__mapsReady`;
396	    s.async = true;
397	    s.onerror = () => { mapsPromise = null; reject(new Error("Impossible de charger Google Maps.")); };
398	    document.head.appendChild(s);
399	  });
400	  return mapsPromise;
401	}
