403	pages.carte = async (view) => {
404	  const [meta, opps] = await Promise.all([loadMeta(), loadOpps(true)]);
405	  view.innerHTML = `
406	    <div class="page-head"><h1>🗺️ Carte</h1><p>Localisation des entreprises collectées.</p></div>
407	    <div class="card toolbar">
408	      <label>Secteur<select id="m-secteur">${options(meta.secteurs, "", "Tous les secteurs")}</select></label>
409	      <label>Score minimum : <span id="m-score-val">0</span><input id="m-score" type="range" min="0" max="100" step="5" value="0"></label>
410	      <span id="m-count" class="muted"></span>
411	    </div>
412	    <div id="map-msg"></div><div id="map"></div>`;
413	
414	  let key = sessionStorage.getItem("cf_gmaps_key") || "";
415	  try { if (!key) key = (await api("/maps-key")).api_key || ""; } catch { /* géré ci-dessous */ }
416	  if (!key) {
417	    $("#map").hidden = true;
418	    $("#map-msg").innerHTML = `<div class="notice">Aucune clé Google Maps. Renseigne <code>GOOGLE_MAPS_API_KEY</code> dans
419	      le fichier <code>.env</code> du serveur, ou saisis une clé pour cette session dans
420	      <a href="#/donnees">Collecte &amp; Import</a>.</div>`;
421	    return;
422	  }
423	  try { await loadGoogleMaps(key); } catch (e) { $("#map-msg").innerHTML = `<div class="notice">${esc(e.message)}</div>`; return; }
424	
425	  const map = new google.maps.Map($("#map"), { center: { lat: 31.6295, lng: -7.9811 }, zoom: 12 });
426	  const info = new google.maps.InfoWindow();
427	  let markers = [];
428	
429	  const draw = () => {
430	    markers.forEach((m) => m.setMap(null)); markers = [];
431	    const sec = $("#m-secteur").value, min = Number($("#m-score").value);
432	    $("#m-score-val").textContent = min;
433	    const pts = opps.filter((o) => typeof o.latitude === "number" && typeof o.longitude === "number"
434	      && (!sec || o.secteur === sec) && (o.score_opportunite || 0) >= min);
435	    const bounds = new google.maps.LatLngBounds();
436	    pts.forEach((o) => {
437	      const pos = { lat: o.latitude, lng: o.longitude };
438	      const m = new google.maps.Marker({ position: pos, map, title: o.nom });
439	      m.addListener("click", () => {
440	        const site = safeUrl(o.site_web);
441	        info.setContent(`<div style="max-width:220px;color:#0f172a"><strong>${esc(o.nom)}</strong><br>
442	          ${esc(o.secteur)} · score ${esc(o.score_opportunite)}<br>${esc(o.adresse || "")}
443	          ${o.email ? `<br>✉️ ${esc(o.email)}` : ""}
444	          ${site ? `<br><a href="${esc(site)}" target="_blank" rel="noopener noreferrer">Site web</a>` : ""}</div>`);
445	        info.open(map, m);
446	      });
447	      markers.push(m); bounds.extend(pos);
448	    });
449	    $("#m-count").textContent = `${pts.length} entreprise(s) affichée(s)`;
450	    if (pts.length > 1) map.fitBounds(bounds);
451	  };
452	  $("#m-secteur").addEventListener("change", draw);
453	  $("#m-score").addEventListener("input", draw);
454	  draw();
455	};
