1	"use strict";
2	/* ===== Pages : Candidatures, Statistiques, Profil & Matching, Collecte & Import ===== */
3	
4	/* ---------- Candidatures ---------- */
5	pages.candidatures = async (view) => {
6	  const [meta, apps, opps] = await Promise.all([loadMeta(), api("/applications"), loadOpps()]);
7	  const today = new Date().toISOString().slice(0, 10);
8	
9	  const col = (statut) => {
10	    const items = apps.filter((a) => a.statut === statut);
11	    return `<div class="col"><h3>${esc(statut)} <span class="chip gray">${items.length}</span></h3>
12	      ${items.map((a) => `<div class="kcard">
13	        <strong>${esc(a.company)}</strong><div class="sub">${esc(a.poste || "")}${a.date_candidature ? " · " + esc(fmt.day(a.date_candidature)) : ""}</div>
14	        ${a.remarque ? `<div class="sub">${esc(a.remarque)}</div>` : ""}
15	        <select data-app-id="${a.id}" aria-label="Changer le statut">${options(meta.statuts, a.statut)}</select>
16	        <button class="btn small danger" data-action="del-app" data-id="${a.id}">🗑 Supprimer</button>
17	      </div>`).join("")}</div>`;
18	  };
19	
20	  view.innerHTML = `
21	    <div class="page-head"><h1>📬 Suivi des candidatures</h1><p>Ajoute et suis tes candidatures auprès des entreprises.</p></div>
22	    <section class="card" style="margin-bottom:1.25rem">
23	      <h2>➕ Ajouter une candidature</h2>
24	      <form id="app-form" class="grid two" style="gap:.25rem 1rem">
25	        <label>Entreprise *<input name="company" required list="app-companies" maxlength="200" placeholder="Nom de l'entreprise">
26	          <datalist id="app-companies">${opps.map((o) => `<option value="${esc(o.nom)}">`).join("")}</datalist></label>
27	        <label>Poste *<input name="poste" required maxlength="200" value="Stage"></label>
28	        <label>Date<input type="date" name="date" value="${today}"></label>
29	        <label>Statut<select name="statut">${options(meta.statuts, "À contacter")}</select></label>
30	        <label style="grid-column:1/-1">Commentaire<textarea name="remarque" rows="2" placeholder="Ex : CV envoyé par e-mail…"></textarea></label>
31	        <p class="error" id="app-error" hidden style="grid-column:1/-1"></p>
32	        <div style="grid-column:1/-1"><button class="btn primary" type="submit">💾 Enregistrer la candidature</button></div>
33	      </form>
34	    </section>
35	    ${apps.length ? "" : `<p class="muted">Aucune candidature pour l'instant.</p>`}
36	    <div class="kanban">${meta.statuts.map(col).join("")}</div>`;
37	
38	  $("#app-form").addEventListener("submit", async (ev) => {
39	    ev.preventDefault();
40	    const f = ev.target;
41	    const match = opps.find((o) => o.nom.toLowerCase() === f.company.value.trim().toLowerCase());
42	    try {
43	      await api("/applications", { method: "POST", json: {
44	        company: f.company.value.trim(), poste: f.poste.value.trim(), statut: f.statut.value,
45	        date_candidature: f.date.value, remarque: f.remarque.value, opportunity_id: match ? match.id : null } });
46	      toast("Candidature enregistrée ✅", "ok"); route();
47	    } catch (e) { const er = $("#app-error"); er.textContent = e.message; er.hidden = false; }
48	  });
49	};
50	
51	document.addEventListener("change", async (ev) => {
52	  const sel = ev.target.closest("select[data-app-id]");
53	  if (!sel) return;
54	  try {
55	    await api(`/applications/${sel.dataset.appId}`, { method: "PATCH", json: { statut: sel.value } });
56	    toast("Statut mis à jour", "ok"); route();
57	  } catch (e) { toast(e.message, "error"); }
58	});
59	
60	actionHandlers["del-app"] = async (el) => {
61	  if (!confirm("Supprimer cette candidature ?")) return;
62	  try { await api(`/applications/${el.dataset.id}`, { method: "DELETE" }); toast("Candidature supprimée"); route(); }
63	  catch (e) { toast(e.message, "error"); }
64	};
65	
66	/* ---------- Statistiques ---------- */
67	const PALETTE = ["#0d9488", "#f59e0b", "#6366f1", "#ec4899", "#22c55e", "#0ea5e9", "#ef4444", "#a855f7", "#14b8a6", "#eab308", "#64748b"];
68	
69	function chartCard(title, id, data) {
70	  const has = Object.values(data || {}).some((v) => v > 0);
71	  return `<section class="card"><h2>${title}</h2>${has
72	    ? `<div class="chart-box"><canvas id="${id}"></canvas></div>`
73	    : `<p class="empty">Pas encore de données.</p>`}</section>`;
74	}
75	
76	function makeChart(id, type, data, opts = {}) {
77	  const el = document.getElementById(id);
78	  if (!el) return;
79	  const labels = Object.keys(data), values = Object.values(data);
80	  const circular = type === "doughnut" || type === "pie";
81	  state.charts.push(new Chart(el, {
82	    type,
83	    data: { labels, datasets: [{ data: values, backgroundColor: circular ? PALETTE : PALETTE[0], borderWidth: 0, borderRadius: circular ? 0 : 6 }] },
84	    options: {
85	      maintainAspectRatio: false, indexAxis: opts.horizontal ? "y" : "x",
86	      plugins: { legend: { display: circular, position: "bottom" } },
87	      scales: circular ? {} : { [opts.horizontal ? "x" : "y"]: { beginAtZero: true, ticks: { precision: 0 } } },
88	    },
89	  }));
90	}
91	
92	pages.statistiques = async (view) => {
93	  const [s, meta] = await Promise.all([api("/stats"), loadMeta()]);
94	  const secteurs = Object.fromEntries(Object.entries(s.par_secteur).sort((a, b) => b[1] - a[1]));
95	  const presence = {
96	    "Avec e-mail": s.presence_numerique.avec_email, "Sans e-mail": s.presence_numerique.sans_email,
97	    "Avec site web": s.presence_numerique.avec_site_web, "Sans site web": s.presence_numerique.sans_site_web,
98	  };
99	  const statuts = Object.fromEntries(meta.statuts.map((k) => [k, s.candidatures_par_statut[k] || 0]));
100	
101	  view.innerHTML = `
102	    <div class="page-head"><h1>📊 Statistiques</h1><p>Analyse des entreprises, des offres et de ta recherche.</p></div>
103	    <div class="grid stats" style="margin-bottom:1.25rem">
104	      ${statCard("🏢", s.total_opportunites, "Entreprises")}${statCard("📄", s.total_offres, "Offres")}
105	      ${statCard("🏷️", s.total_secteurs, "Secteurs")}${statCard("✉️", s.entreprises_avec_email, "Avec e-mail")}
106	      ${statCard("📨", s.cv_envoyes, "CV envoyés")}${statCard("⭐", s.favoris, "Favoris")}
107	    </div>
108	    ${window.Chart ? "" : `<div class="notice">Les graphiques n'ont pas pu être chargés (connexion à cdnjs.cloudflare.com bloquée ?).</div>`}
109	    <div class="grid two">
110	      ${chartCard("🏢 Entreprises par secteur", "ch-secteur", secteurs)}
111	      ${chartCard("🎓 Offres par type de stage", "ch-stage", s.offres_par_type_stage)}
112	      ${chartCard("📋 Offres par type de contrat", "ch-contrat", s.offres_par_contrat)}
113	      ${chartCard("🌐 Présence numérique des entreprises", "ch-presence", presence)}
114	      ${chartCard("📬 Candidatures par statut", "ch-statut", statuts)}
115	    </div>`;
116	
117	  if (!window.Chart) return;
118	  Chart.defaults.color = getComputedStyle(document.documentElement).getPropertyValue("--muted").trim() || "#64748b";
119	  makeChart("ch-secteur", "bar", secteurs);
120	  makeChart("ch-stage", "doughnut", s.offres_par_type_stage);
121	  makeChart("ch-contrat", "bar", s.offres_par_contrat);
122	  makeChart("ch-presence", "bar", presence, { horizontal: true });
123	  makeChart("ch-statut", "bar", statuts);
124	};
125	
126	/* ---------- Profil & Matching ---------- */
127	async function runMatching() {
128	  const min = Number($("#match-min").value);
129	  $("#match-min-val").textContent = min;
130	  const box = $("#match-results");
131	  box.innerHTML = `<p class="loading">Calcul…</p>`;
132	  try {
133	    const rows = await api("/matching", { params: { min_score: min } });
134	    await loadOpps();
135	    box.innerHTML = rows.length ? `<div class="table-wrap"><table>
136	      <thead><tr><th>Entreprise</th><th>Match</th><th>Score d'opportunité</th><th>Mots-clés</th><th></th></tr></thead><tbody>
137	      ${rows.slice(0, 40).map((o) => `<tr>
138	        <td><strong>${esc(o.nom)}</strong><div class="sub">${esc(o.secteur)} · ${esc(o.adresse || "")}</div></td>
139	        <td>${scoreBadge(o.match_score)}</td><td>${scoreBadge(o.score_opportunite)}</td>
140	        <td class="sub">${esc(o.mots_cles || "—")}</td>
141	        <td><button class="btn small primary" data-action="send-cv" data-id="${o.id}" ${(o.email || "").trim() ? "" : "disabled"}>✉️ CV</button></td></tr>`).join("")}
142	      </tbody></table></div><p class="muted">${rows.length} résultat(s), 40 affichés au maximum.</p>`
143	      : `<p class="empty card">Aucune entreprise ne dépasse ce seuil. Complète tes compétences ou baisse le seuil.</p>`;
144	  } catch (e) { box.innerHTML = `<p class="error">${esc(e.message)}</p>`; }
145	}
146	
147	pages.profil = async (view) => {
148	  const profile = await api("/profile");
149	  view.innerHTML = `
150	    <div class="page-head"><h1>🎯 Profil &amp; Matching</h1>
151	      <p>Renseigne tes compétences pour voir les entreprises qui te correspondent le mieux.</p></div>
152	    <section class="card" style="margin-bottom:1.25rem">
153	      <form id="profile-form">
154	        <label>Compétences (séparées par des virgules)
155	          <textarea name="skills" rows="3" placeholder="python, machine learning, data, cloud">${esc(profile.skills || "")}</textarea></label>
156	        <div class="grid two" style="gap:.5rem 1rem">
157	          <label>Années d'expérience<input type="number" name="experience_years" min="0" max="50" step="0.5" value="${esc(profile.experience_years || 0)}"></label>
158	          <label>Courte présentation<input name="bio" maxlength="500" value="${esc(profile.bio || "")}"></label>
159	        </div>
160	        <button class="btn primary" type="submit">💾 Enregistrer mon profil</button>
161	      </form>
162	    </section>
163	    <section>
164	      <h2>🤖 Entreprises recommandées</h2>
165	      <p class="muted">Indicatif : 60 % de compétences en commun avec les mots-clés de l'entreprise (surtout tirés de son nom),
166	        40 % du score d'opportunité.</p>
167	      <label>Match minimum : <span id="match-min-val">20</span>
168	        <input id="match-min" type="range" min="0" max="100" step="5" value="20" style="max-width:340px"></label>
169	      <div id="match-results"></div>
170	    </section>`;
171	
172	  $("#profile-form").addEventListener("submit", async (ev) => {
173	    ev.preventDefault();
174	    const f = ev.target;
175	    try {
176	      await api("/profile", { method: "POST", json: {
177	        skills: f.skills.value, experience_years: Number(f.experience_years.value) || 0,
178	        bio: f.bio.value, cv_filename: profile.cv_filename || "" } });
179	      toast("Profil enregistré ✅", "ok"); runMatching();
180	    } catch (e) { toast(e.message, "error"); }
181	  });
182	  $("#match-min").addEventListener("change", runMatching);
183	  $("#match-min").addEventListener("input", () => { $("#match-min-val").textContent = $("#match-min").value; });
184	  runMatching();
185	};
186	
187	/* ---------- Collecte & Import ---------- */
188	const EXTRA_QUERIES = ["entreprise informatique", "société IT", "startup tech", "data science",
189	  "développement logiciel", "cloud computing", "cybersécurité", "agence digitale"];
190	
191	function reportHtml(report) {
192	  const labels = {
193	    lignes_lues: "Lignes lues", sans_nom_supprimees: "Sans nom (supprimées)", fermees_supprimees: "Fiches fermées (supprimées)",
194	    doublons_supprimes: "Doublons (supprimés)", hors_secteur_supprimees: "Hors secteur IT/IA (supprimées)",
195	    lignes_conservees: "Lignes conservées", opportunites_ajoutees: "Entreprises ajoutées / mises à jour",
196	    ajoutees: "Offres ajoutées", ignorees: "Offres ignorées (doublons ou titre vide)",
197	  };
198	  return `<div class="report">${Object.entries(report).map(([k, v]) => `${esc(labels[k] || k)} : <strong>${esc(v)}</strong>`).join("<br>")}</div>`;
199	}
200	
201	pages.donnees = async (view) => {
202	  const meta = await loadMeta();
203	  view.innerHTML = `
204	    <div class="page-head"><h1>⚙️ Collecte &amp; Import</h1><p>Alimente l'application en entreprises et en offres.</p></div>
205	    <div class="grid two">
206	
207	      <section class="card">
208	        <h2>🔄 Collecte Google Places</h2>
209	        <form id="collect-form">
210	          <label>Requête<input name="query" value="Intelligence Artificielle OR Informatique"></label>
211	          <label>Coordonnées (lat,lng)<input name="location" value="31.6295,-7.9811"></label>
212	          <label>Rayon : <span id="radius-val">15</span> km<input name="radius" type="range" min="1000" max="50000" step="1000" value="15000"></label>
213	          <label class="inline"><input name="wide" type="checkbox">Recherche élargie (plusieurs requêtes IT/IA)</label>
214	          <label>Clé API Google (optionnel, cette session uniquement)
215	            <input name="apikey" type="password" autocomplete="off" placeholder="Remplace la clé du serveur"
216	                   value="${esc(sessionStorage.getItem("cf_gmaps_key") || "")}"></label>
217	          <button class="btn primary" type="submit" id="collect-btn">Collecter</button>
218	          <div id="collect-out"></div>
219	        </form>
220	      </section>
221	
222	      <section class="card">
223	        <h2>📂 Importer des entreprises (Excel)</h2>
224	        <p class="muted">Colonnes : <code>entreprise</code> (obligatoire), type, secteur, adresse, lat, lon, note, site_web,
225	          telephone, <code>email</code>, statut_google.</p>
226	        <form id="excel-form">
227	          <label>Fichier .xlsx<input type="file" name="file" accept=".xlsx,.xls" required></label>
228	          <label class="inline"><input type="checkbox" name="only" checked>Garder uniquement Informatique / IA</label>
229	          <button class="btn primary" type="submit">Importer</button>
230	          <div id="excel-out"></div>
231	        </form>
232	      </section>
233	
234	      <section class="card">
235	        <h2>📄 Importer des offres (Excel ou CSV)</h2>
236	        <p class="muted">Colonnes reconnues : <code>titre</code> (obligatoire), entreprise, contrat, type de stage,
237	          ville, date de publication, lien, description.</p>
238	        <form id="offers-form">
239	          <label>Fichier .xlsx ou .csv<input type="file" name="file" accept=".xlsx,.xls,.csv" required></label>
240	          <button class="btn primary" type="submit">Importer</button>
241	          <div id="offers-out"></div>
242	        </form>
243	      </section>
244	
245	      <section class="card">
246	        <h2>➕ Ajouter une entreprise</h2>
247	        <form id="manual-form" class="grid two" style="gap:0 .75rem">
248	          <label style="grid-column:1/-1">Nom *<input name="nom" required maxlength="200"></label>
249	          <label>Secteur<select name="secteur">${options(meta.secteurs, "", "Détection automatique")}</select></label>
250	          <label>E-mail<input type="email" name="email" maxlength="254"></label>
251	          <label>Téléphone<input name="telephone" maxlength="40"></label>
252	          <label>Site web<input name="site_web" maxlength="300"></label>
253	          <label style="grid-column:1/-1">Adresse<input name="adresse" maxlength="300"></label>
254	          <label>Latitude<input name="lat" type="number" step="any"></label>
255	          <label>Longitude<input name="lng" type="number" step="any"></label>
256	          <label>Score (0-100)<input name="score" type="number" min="0" max="100" value="50"></label>
257	          <p class="error" id="manual-error" hidden style="grid-column:1/-1"></p>
258	          <div style="grid-column:1/-1"><button class="btn primary" type="submit">Ajouter</button></div>
259	        </form>
260	      </section>
261	
262	      <section class="card">
263	        <h2>📥 Exports</h2>
264	        <p class="muted">Tes données (favoris, candidatures) au format tableur.</p>
265	        <div class="actions">
266	          <button class="btn" data-action="export" data-path="/export/complet" data-file="resultats_analyse_et_suivi.xlsx">Export complet (.xlsx)</button>
267	          <button class="btn" data-action="export" data-path="/export/avant-apres" data-file="donnees_avant_apres.xlsx">Avant / après nettoyage (.xlsx)</button>
268	          <button class="btn" data-action="export" data-path="/opportunities/export" data-file="opportunites.csv">Entreprises (.csv)</button>
269	        </div>
270	      </section>
271	    </div>`;
272	
273	  const out = (id, html) => { $(id).innerHTML = html; };
274	  const radius = $("#collect-form").radius;
275	  radius.addEventListener("input", () => { $("#radius-val").textContent = Math.round(radius.value / 1000); });
276	
277	  $("#collect-form").addEventListener("submit", async (ev) => {
278	    ev.preventDefault();
279	    const f = ev.target, btn = $("#collect-btn");
280	    const key = f.apikey.value.trim();
281	    if (key) sessionStorage.setItem("cf_gmaps_key", key); else sessionStorage.removeItem("cf_gmaps_key");
282	    const queries = f.wide.checked ? [f.query.value, ...EXTRA_QUERIES] : [f.query.value];
283	    btn.disabled = true; let total = 0, errors = [];
284	    for (let i = 0; i < queries.length; i++) {
285	      out("#collect-out", `<p class="muted">« ${esc(queries[i])} » (${i + 1}/${queries.length})…</p>`);
286	      try {
287	        const r = await api("/opportunities/refresh", { method: "POST",
288	          params: { query: queries[i], location: f.location.value, radius: f.radius.value },
289	          headers: key ? { "X-Google-Api-Key": key } : {} });
290	        total += r.count || 0;
291	      } catch (e) { errors.push(`« ${queries[i]} » : ${e.message}`); if (e.status === 401) break; }
292	    }
293	    btn.disabled = false; state.opps = null;
294	    out("#collect-out", `<div class="report">${total} entreprise(s) collectée(s) ou mise(s) à jour.
295	      ${errors.length ? `<br><span class="error">${errors.map(esc).join("<br>")}</span>` : ""}</div>`);
296	    if (total) toast(`${total} entreprise(s) collectée(s) ✅`, "ok");
297	  });
298	
299	  const uploader = (formId, outId, path, extra) => $(formId).addEventListener("submit", async (ev) => {
300	    ev.preventDefault();
301	    const f = ev.target, file = f.file.files[0];
302	    if (!file) return;
303	    const fd = new FormData(); fd.append("file", file);
304	    const btn = f.querySelector("button[type=submit]"); btn.disabled = true;
305	    try {
306	      const r = await api(path, { method: "POST", form: fd, params: extra ? extra(f) : undefined });
307	      out(outId, reportHtml(r.report)); state.opps = null; toast("Import terminé ✅", "ok");
308	    } catch (e) { out(outId, `<p class="error">${esc(e.message)}</p>`); }
309	    btn.disabled = false;
310	  });
311	  uploader("#excel-form", "#excel-out", "/opportunities/import-excel", (f) => ({ only_it_ai: f.only.checked }));
312	  uploader("#offers-form", "#offers-out", "/offers/import");
313	
314	  $("#manual-form").addEventListener("submit", async (ev) => {
315	    ev.preventDefault();
316	    const f = ev.target, num = (v) => (v === "" ? null : Number(v));
317	    try {
318	      await api("/opportunities/manual", { method: "POST", json: {
319	        nom: f.nom.value, secteur: f.secteur.value, email: f.email.value, telephone: f.telephone.value,
320	        site_web: f.site_web.value, adresse: f.adresse.value, latitude: num(f.lat.value), longitude: num(f.lng.value),
321	        score_opportunite: Number(f.score.value) || 0 } });
322	      toast("Entreprise ajoutée ✅", "ok"); f.reset(); state.opps = null; $("#manual-error").hidden = true;
323	    } catch (e) { const er = $("#manual-error"); er.textContent = e.message; er.hidden = false; }
324	  });
325	};
326	
327	actionHandlers["export"] = (el) => downloadFile(el.dataset.path, el.dataset.file);
