2	/* ===== Noyau : état, API, utilitaires, modales ===== */
3	
4	const $ = (sel, root = document) => root.querySelector(sel);
5	const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
6	
7	// Échappement HTML : TOUTE donnée issue de l'API (noms Google, Excel, saisies) passe par esc().
8	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
9	  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
10	
11	// URL http(s) uniquement (bloque javascript:, data:…). Ajoute https:// si le schéma manque.
12	function safeUrl(u) {
13	  u = String(u ?? "").trim();
14	  if (!u) return "";
15	  if (/^https?:\/\//i.test(u)) return u;
16	  if (/^[\w-]+(\.[\w-]+)+(\/.*)?$/.test(u)) return "https://" + u;
17	  return "";
18	}
19	
20	const state = {
21	  token: localStorage.getItem("cf_token"),
22	  user: JSON.parse(localStorage.getItem("cf_user") || "null"),
23	  meta: null,
24	  opps: null,        // cache des entreprises (rechargé après chaque modification)
25	  charts: [],
26	};
27	
28	/* ---------- API ---------- */
29	class ApiError extends Error {
30	  constructor(message, status) { super(message); this.status = status; }
31	}
32	
33	function errorText(data, fallback) {
34	  const d = data && data.detail;
35	  if (typeof d === "string") return d;
36	  if (Array.isArray(d)) {   // erreurs de validation FastAPI/Pydantic
37	    return d.map((e) => String(e.msg || "").replace(/^Value error, /, "")).filter(Boolean).join(" · ") || fallback;
38	  }
39	  return fallback;
40	}
41	
42	async function api(path, { method = "GET", params, json, form, headers = {}, blob = false } = {}) {
43	  let url = "/api" + path;
44	  if (params) {
45	    const qs = new URLSearchParams();
46	    Object.entries(params).forEach(([k, v]) => { if (v !== undefined && v !== null && v !== "") qs.set(k, v); });
47	    if ([...qs].length) url += "?" + qs.toString();
48	  }
49	  const opts = { method, headers: { ...headers } };
50	  if (state.token) opts.headers.Authorization = "Bearer " + state.token;
51	  if (json !== undefined) { opts.headers["Content-Type"] = "application/json"; opts.body = JSON.stringify(json); }
52	  if (form) opts.body = form;
53	
54	  let res;
55	  try { res = await fetch(url, opts); }
56	  catch { throw new ApiError("Serveur injoignable. Vérifie que l'application est démarrée.", 0); }
57	
58	  if (!res.ok) {
59	    let data = null;
60	    try { data = await res.json(); } catch { /* corps non JSON */ }
61	    if (res.status === 401 && state.token) { logout(true); }
62	    throw new ApiError(errorText(data, `Erreur ${res.status}`), res.status);
63	  }
64	  return blob ? res.blob() : res.json();
65	}
66	
67	/* ---------- Session ---------- */
68	function setSession(data) {
69	  state.token = data.access_token;
70	  state.user = { username: data.username, is_admin: data.is_admin };
71	  localStorage.setItem("cf_token", state.token);
72	  localStorage.setItem("cf_user", JSON.stringify(state.user));
73	}
74	
75	function logout(expired = false) {
76	  state.token = null; state.user = null; state.meta = null; state.opps = null;
77	  localStorage.removeItem("cf_token");
78	  localStorage.removeItem("cf_user");
79	  sessionStorage.removeItem("cf_gmaps_key");
80	  destroyCharts();
81	  if (typeof showAuth === "function") showAuth(expired ? "Session expirée, reconnecte-toi." : "");
82	}
83	
84	/* ---------- Interface ---------- */
85	function toast(msg, type = "") {
86	  const el = document.createElement("div");
87	  el.className = "toast " + type;
88	  el.textContent = msg;
89	  $("#toasts").appendChild(el);
90	  setTimeout(() => el.remove(), type === "error" ? 6000 : 3500);
91	}
92	
93	function openModal(html) {
94	  const dlg = $("#modal");
95	  dlg.innerHTML = `<div class="modal-body">${html}</div>`;
96	  if (!dlg.open) dlg.showModal();
97	  return dlg;
98	}
99	function closeModal() { const d = $("#modal"); if (d.open) d.close(); }
100	
101	function destroyCharts() { state.charts.forEach((c) => c.destroy()); state.charts = []; }
102	
103	const fmt = {
104	  // Horodatage SQLite (UTC, "YYYY-MM-DD HH:MM:SS") -> date locale
105	  ts(s) {
106	    if (!s) return "";
107	    const d = new Date(String(s).replace(" ", "T") + "Z");
108	    return isNaN(d) ? esc(s) : d.toLocaleDateString("fr-FR");
109	  },
110	  // Date ISO "YYYY-MM-DD" -> date locale (sans décalage de fuseau)
111	  day(s) {
112	    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || "");
113	    return m ? `${m[3]}/${m[2]}/${m[1]}` : (s || "");
114	  },
115	};
116	
117	const canEdit = (rec) => !!state.user && (state.user.is_admin || rec.added_by === state.user.username);
118	
119	function scoreBadge(score) {
120	  const n = Math.max(0, Math.min(100, Math.round(Number(score) || 0)));
121	  return `<span class="score">${n}<span class="bar"><i style="width:${n}%"></i></span></span>`;
122	}
123	
124	function options(list, selected = "", allLabel = null) {
125	  const first = allLabel === null ? "" : `<option value="">${esc(allLabel)}</option>`;
126	  return first + list.map((v) => `<option value="${esc(v)}"${v === selected ? " selected" : ""}>${esc(v)}</option>`).join("");
127	}
128	
129	function debounce(fn, ms = 250) {
130	  let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
131	}
132	
133	async function loadMeta() {
134	  if (!state.meta) state.meta = await api("/meta");
135	  return state.meta;
136	}
137	
138	async function loadOpps(force = false) {
139	  if (force || !state.opps) state.opps = await api("/opportunities", { params: { min_score: 0 } });
140	  return state.opps;
141	}
142	
143	// Téléchargement d'un fichier protégé (l'en-tête Authorization interdit un simple lien <a href>)
144	async function downloadFile(path, filename) {
145	  try {
146	    const blob = await api(path, { blob: true });
147	    const a = document.createElement("a");
148	    a.href = URL.createObjectURL(blob);
149	    a.download = filename;
150	    document.body.appendChild(a);
151	    a.click();
152	    a.remove();
153	    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
154	  } catch (e) { toast(e.message, "error"); }
155	}
156	
157	// Délégation d'événements : les boutons portent data-action / data-id (aucun onclick inline)
158	const actionHandlers = {};
159	document.addEventListener("click", (ev) => {
160	  const el = ev.target.closest("[data-action]");
161	  if (!el || el.disabled) return;
162	  const handler = actionHandlers[el.dataset.action];
163	  if (handler) { ev.preventDefault(); handler(el, ev); }
164	});
165	document.addEventListener("click", (ev) => {
166	  const dlg = $("#modal");
167	  if (ev.target === dlg || ev.target.closest("[data-close]")) closeModal();
168	});
