  charts: [],
};

/* ---------- API ---------- */
class ApiError extends Error {
  constructor(message, status) { super(message); this.status = status; }
}

function errorText(data, fallback) {
  const d = data && data.detail;
  if (typeof d === "string") return d;
  if (Array.isArray(d)) {   // erreurs de validation FastAPI/Pydantic
    return d.map((e) => String(e.msg || "").replace(/^Value error, /, "")).filter(Boolean).join(" · ") || fallback;
  }
  return fallback;
}

async function api(path, { method = "GET", params, json, form, headers = {}, blob = false } = {}) {
  let url = "/api" + path;
  if (params) {
    const qs = new URLSearchParams();
    Object.entries(params).forEach(([k, v]) => { if (v !== undefined && v !== null && v !== "") qs.set(k, v); });
    if ([...qs].length) url += "?" + qs.toString();
  }
  const opts = { method, headers: { ...headers } };
  if (state.token) opts.headers.Authorization = "Bearer " + state.token;
  if (json !== undefined) { opts.headers["Content-Type"] = "application/json"; opts.body = JSON.stringify(json); }
  if (form) opts.body = form;

  let res;
  try { res = await fetch(url, opts); }
  catch { throw new ApiError("Serveur injoignable. Vérifie que l'application est démarrée.", 0); }

  if (!res.ok) {
    let data = null;
    try { data = await res.json(); } catch { /* corps non JSON */ }
    if (res.status === 401 && state.token) { logout(true); }
    throw new ApiError(errorText(data, `Erreur ${res.status}`), res.status);
  }
  return blob ? res.blob() : res.json();
}

/* ---------- Session ---------- */
function setSession(data) {
  state.token = data.access_token;
  state.user = { username: data.username, is_admin: data.is_admin };
  localStorage.setItem("cf_token", state.token);
  localStorage.setItem("cf_user", JSON.stringify(state.user));
}

function logout(expired = false) {
  state.token = null; state.user = null; state.meta = null; state.opps = null;
  localStorage.removeItem("cf_token");
  localStorage.removeItem("cf_user");
  sessionStorage.removeItem("cf_gmaps_key");
  destroyCharts();
  if (typeof showAuth === "function") showAuth(expired ? "Session expirée, reconnecte-toi." : "");
}

/* ---------- Interface ---------- */
function toast(msg, type = "") {
  const el = document.createElement("div");
  el.className = "toast " + type;
  el.textContent = msg;
  $("#toasts").appendChild(el);
  setTimeout(() => el.remove(), type === "error" ? 6000 : 3500);
}

function openModal(html) {
  const dlg = $("#modal");
  dlg.innerHTML = `<div class="modal-body">${html}</div>`;
  if (!dlg.open) dlg.showModal();
  return dlg;
}
function closeModal() { const d = $("#modal"); if (d.open) d.close(); }

function destroyCharts() { state.charts.forEach((c) => c.destroy()); state.charts = []; }

const fmt = {
  // Horodatage SQLite (UTC, "YYYY-MM-DD HH:MM:SS") -> date locale
  ts(s) {
    if (!s) return "";
    const d = new Date(String(s).replace(" ", "T") + "Z");
    return isNaN(d) ? esc(s) : d.toLocaleDateString("fr-FR");
  },
  // Date ISO "YYYY-MM-DD" -> date locale (sans décalage de fuseau)
  day(s) {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || "");
    return m ? `${m[3]}/${m[2]}/${m[1]}` : (s || "");
  },
};

const canEdit = (rec) => !!state.user && (state.user.is_admin || rec.added_by === state.user.username);

function scoreBadge(score) {
  const n = Math.max(0, Math.min(100, Math.round(Number(score) || 0)));
  return `<span class="score">${n}<span class="bar"><i style="width:${n}%"></i></span></span>`;
}

function options(list, selected = "", allLabel = null) {
  const first = allLabel === null ? "" : `<option value="">${esc(allLabel)}</option>`;
  return first + list.map((v) => `<option value="${esc(v)}"${v === selected ? " selected" : ""}>${esc(v)}</option>`).join("");
}

function debounce(fn, ms = 250) {
  let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
}

async function loadMeta() {
  if (!state.meta) state.meta = await api("/meta");
  return state.meta;
}

async function loadOpps(force = false) {
  if (force || !state.opps) state.opps = await api("/opportunities", { params: { min_score: 0 } });
  return state.opps;
}

// Téléchargement d'un fichier protégé (l'en-tête Authorization interdit un simple lien <a href>)
async function downloadFile(path, filename) {
  try {
    const blob = await api(path, { blob: true });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  } catch (e) { toast(e.message, "error"); }
}

// Délégation d'événements : les boutons portent data-action / data-id (aucun onclick inline)
const actionHandlers = {};
document.addEventListener("click", (ev) => {
  const el = ev.target.closest("[data-action]");
  if (!el || el.disabled) return;
  const handler = actionHandlers[el.dataset.action];
  if (handler) { ev.preventDefault(); handler(el, ev); }
});
document.addEventListener("click", (ev) => {
  const dlg = $("#modal");
  if (ev.target === dlg || ev.target.closest("[data-close]")) closeModal();
});

"""Sécurité : hachage des mots de passe (scrypt, stdlib) et jetons JWT (HS256)."""
import base64
import hashlib
import hmac
import logging
import os
import secrets
import time
from datetime import datetime, timedelta, timezone
from typing import Optional

import jwt

logger = logging.getLogger("career_finder.security")

JWT_ALGORITHM = "HS256"
TOKEN_TTL_HOURS = int(os.getenv("TOKEN_TTL_HOURS", "12"))

# scrypt : N=2**14, r=8, p=1 (valeurs recommandées par OWASP pour un usage interactif)
_SCRYPT_N, _SCRYPT_R, _SCRYPT_P = 2**14, 8, 1


def _load_secret() -> str:
    secret = os.getenv("SECRET_KEY", "")
    if secret and len(secret) >= 32:
        return secret
    generated = secrets.token_urlsafe(48)
    logger.warning(
        "SECRET_KEY absente ou trop courte (<32 car.) : une clé temporaire est générée. "
        "Les sessions seront invalidées à chaque redémarrage. Définis SECRET_KEY dans .env."
    )
    return generated


SECRET_KEY = _load_secret()


# ---------- Mots de passe ----------

def hash_password(password: str) -> str:
    salt = os.urandom(16)
    dk = hashlib.scrypt(password.encode("utf-8"), salt=salt, n=_SCRYPT_N, r=_SCRYPT_R, p=_SCRYPT_P)
    return "scrypt$" + base64.b64encode(salt).decode() + "$" + base64.b64encode(dk).decode()


def verify_password(password: str, stored: str) -> bool:
    try:
        scheme, salt_b64, hash_b64 = stored.split("$")
        if scheme != "scrypt":
            return False
        salt = base64.b64decode(salt_b64)
        expected = base64.b64decode(hash_b64)
        dk = hashlib.scrypt(password.encode("utf-8"), salt=salt, n=_SCRYPT_N, r=_SCRYPT_R, p=_SCRYPT_P)
        return hmac.compare_digest(dk, expected)
    except (ValueError, TypeError):
        return False


# ---------- JWT ----------

def create_access_token(username: str, is_admin: bool = False) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "sub": username,
        "adm": bool(is_admin),
        "iat": now,
        "exp": now + timedelta(hours=TOKEN_TTL_HOURS),
    }
    return jwt.encode(payload, SECRET_KEY, algorithm=JWT_ALGORITHM)


def decode_access_token(token: str) -> Optional[dict]:
    """Retourne le payload si le jeton est valide et non expiré, sinon None."""
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[JWT_ALGORITHM])
    except jwt.PyJWTError:
        return None


# ---------- Limiteur de tentatives de connexion (en mémoire) ----------

class LoginRateLimiter:
    """Bloque un identifiant après `max_attempts` échecs dans `window` secondes."""

    def __init__(self, max_attempts: int = 5, window: int = 300):
        self.max_attempts = max_attempts
        self.window = window
        self._failures: dict = {}

    def _recent(self, key: str) -> list:
        now = time.time()
        recent = [t for t in self._failures.get(key, []) if now - t < self.window]
        self._failures[key] = recent
        return recent

    def is_blocked(self, key: str) -> bool:
        return len(self._recent(key)) >= self.max_attempts

    def register_failure(self, key: str) -> None:
        self._recent(key).append(time.time())

    def reset(self, key: str) -> None:
        self._failures.pop(key, None)

import time

import requests

PLACES_SEARCH_URL = "https://places.googleapis.com/v1/places:searchText"

# Le nouveau format d'API exige de déclarer explicitement les champs voulus
# (FieldMask), pour limiter la facturation aux données réellement utilisées.
FIELD_MASK = (
    "places.id,places.displayName,places.formattedAddress,"
    "places.location,places.rating,places.types,"
    "places.websiteUri,places.internationalPhoneNumber,places.googleMapsUri,"
    "nextPageToken"
)


def fetch_it_companies_google(
    api_key: str,
    location: str = "31.6295,-7.9811",
    radius: int = 10000,
    query: str = "Intelligence Artificielle OR Informatique",
    max_pages: int = 3,
) -> list:
    """
    Récupère les entreprises IT / IA via l'API Places (New) - Text Search,
    en suivant la pagination (jusqu'à max_pages pages de 20 résultats
    chacune, soit 60 résultats max par recherche).
    """
    try:
        lat_str, lng_str = location.split(",")
        lat, lng = float(lat_str), float(lng_str)
    except (ValueError, AttributeError):
        lat, lng = 31.6295, -7.9811

    headers = {
        "Content-Type": "application/json",
        "X-Goog-Api-Key": api_key,
        "X-Goog-FieldMask": FIELD_MASK,
    }

    all_results = []
    page_token = None

    for _ in range(max_pages):
        body = {
            "textQuery": query,
            "locationBias": {
                "circle": {
                    "center": {"latitude": lat, "longitude": lng},
                    "radius": radius,
                }
            },
            "pageSize": 20,
        }
        if page_token:
            # Laisser le temps au pageToken de devenir valide côté Google
            time.sleep(2)
            body["pageToken"] = page_token

        try:
            response = requests.post(PLACES_SEARCH_URL, json=body, headers=headers, timeout=15)
        except requests.RequestException:
            break

        if response.status_code != 200:
            break

        payload = response.json()
        all_results.extend(payload.get("places", []))
        page_token = payload.get("nextPageToken")
        if not page_token:
            break

    return all_results
